//! Tasks T-2 and T-3b: the fixture guard (architecture 8.4) and the raw manifest (architecture 8.2 (a)).
//!
//! `tests/golden/exp_raw.tsv` (repository root) has one line per binary part of the 229 `*_exp_*.dmp` fixtures
//! (450 parts in 436 table sections; the counts are those of `common::TOTALS`). It was generated by `tests/golden/gen_exp_raw.py` from the Analyst's
//! `docs/formats/tools/exp_parse.py`; the serialisations that are hashed (raw fields with the chain
//! serialisation of ADR-29 item 6, LOB values, the assembled values of each LONG column) are documented in
//! that script and in `oradmp_core::exp::rows`. The row counts of `truth_counts.txt` are read from the
//! fixture folders. The walker with hashing reproduces every line.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::panic
)]

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::io::Cursor;
use std::path::{Path, PathBuf};

use oradmp_core::exp::items::{walk, walk_path, WalkEnd, WalkOptions, WalkReport};
use oradmp_core::exp::table::PathKind;
use sha2::{Digest, Sha256};

mod common;
use common::TOTALS;

const FOLDERS: [&str; 3] = ["18c", "11g", "11g-cp1251"];

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn fixtures() -> PathBuf {
    root().join("corpus/fixtures")
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().fold(String::new(), |mut s, b| {
        write!(s, "{b:02x}").unwrap();
        s
    })
}

fn sha_of(path: &Path) -> String {
    hex(&Sha256::digest(std::fs::read(path).unwrap()))
}

// ---------------------------------------------------------------------------------------------
// fixture guard
// ---------------------------------------------------------------------------------------------

/// Checks a folder against its `SHA256SUMS`; returns one problem text per difference, listed file that is
/// missing or changed, and `.dmp` file that is not listed.
fn check_folder(dir: &Path) -> Vec<String> {
    let mut problems = Vec::new();
    let sums = std::fs::read_to_string(dir.join("SHA256SUMS")).unwrap();
    let mut listed = BTreeSet::new();
    for line in sums.lines().filter(|l| !l.trim().is_empty()) {
        let (digest, name) = line.split_once("  ").unwrap();
        let name = name.trim_start_matches("./");
        listed.insert(name.to_string());
        let path = dir.join(name);
        if !path.exists() {
            problems.push(format!("{name}: listed but missing"));
        } else if sha_of(&path) != digest {
            problems.push(format!("{name}: checksum differs"));
        }
    }
    for e in std::fs::read_dir(dir).unwrap() {
        let name = e.unwrap().file_name().to_string_lossy().into_owned();
        if name.ends_with(".dmp") && !listed.contains(&name) {
            problems.push(format!("{name}: not listed"));
        }
    }
    problems
}

#[test]
fn x_fixture_checksums_match_the_three_sha256sums_files() {
    let mut lines = 0usize;
    let mut dmp = 0usize;
    for f in FOLDERS {
        let dir = fixtures().join(f);
        let problems = check_folder(&dir);
        assert!(problems.is_empty(), "{f}: {problems:?}");
        let sums = std::fs::read_to_string(dir.join("SHA256SUMS")).unwrap();
        lines += sums.lines().count();
        dmp += sums.lines().filter(|l| l.ends_with(".dmp")).count();
    }
    // The guard keeps explicit numbers (T-3d): its purpose is to notice a file that arrives without a design
    // update. 317 lines, 235 of them name a `.dmp` (211 exp + 34 Data Pump files); session 10 (`ru_lob2_*`,
    // `truth_lob_ru.txt`, `truth_r045.txt`, logs) made 313 / 233 grow to 317 / 235 (rules v3.5; Architect
    // session 8: `sha256sum -c` OK in all three folders, 147 / 140 / 30 lines). T-19: the ten files of Analyst
    // session 17 and the five truth files make 332 / 245 (python over the three `SHA256SUMS`). T-19b: the 18 EXP
    // files of Analyst sessions 19 and 20, their logs, the 10 truth files and `11g/truth_r049.txt` make 360 / 263
    // (python over the three `SHA256SUMS`; 263 `.dmp` = 229 EXP + 34 Data Pump).
    assert_eq!((lines, dmp), (360, 263));
}

/// A scratch folder below `target/` with a copy of the smallest fixture and a `SHA256SUMS` for it.
fn scratch_copy(name: &str) -> PathBuf {
    let target = root().join("target/t2_guard").join(name);
    let _ = std::fs::remove_dir_all(&target);
    std::fs::create_dir_all(&target).unwrap();
    let src = fixtures().join("18c");
    let mut best: Option<(u64, PathBuf)> = None;
    for e in std::fs::read_dir(&src).unwrap() {
        let p = e.unwrap().path();
        if p.extension().is_some_and(|x| x == "dmp") {
            let len = std::fs::metadata(&p).unwrap().len();
            if best.as_ref().is_none_or(|(l, _)| len < *l) {
                best = Some((len, p));
            }
        }
    }
    let file = best.unwrap().1;
    let fname = file.file_name().unwrap().to_string_lossy().into_owned();
    std::fs::copy(&file, target.join(&fname)).unwrap();
    std::fs::write(
        target.join("SHA256SUMS"),
        format!("{}  ./{fname}\n", sha_of(&file)),
    )
    .unwrap();
    target
}

#[test]
fn x_guard_fails_on_a_changed_byte_a_missing_file_and_an_unlisted_dump() {
    let dir = scratch_copy("changed");
    assert!(check_folder(&dir).is_empty(), "the untouched copy passes");
    let dmp = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .find(|p| p.extension().is_some_and(|x| x == "dmp"))
        .unwrap();
    // one byte in the middle, one bit
    let mut bytes = std::fs::read(&dmp).unwrap();
    let mid = bytes.len() / 2;
    bytes[mid] ^= 0x01;
    std::fs::write(&dmp, &bytes).unwrap();
    let problems = check_folder(&dir);
    assert_eq!(problems.len(), 1, "{problems:?}");
    assert!(problems[0].ends_with("checksum differs"));
    // a missing file
    std::fs::remove_file(&dmp).unwrap();
    let problems = check_folder(&dir);
    assert!(problems[0].ends_with("listed but missing"), "{problems:?}");
    // an unlisted dump
    let dir = scratch_copy("unlisted");
    std::fs::write(dir.join("extra_exp_18c.dmp"), b"x").unwrap();
    let problems = check_folder(&dir);
    assert_eq!(problems, vec!["extra_exp_18c.dmp: not listed".to_string()]);
}

// ---------------------------------------------------------------------------------------------
// the raw manifest
// ---------------------------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq, Eq)]
struct Line {
    file: String,
    ordinal: u32,
    part: u32,
    table: String,
    partition: String,
    subpart: String,
    cols: Vec<(u16, u16)>,
    direct: bool,
    rows: u64,
    nulls: u64,
    sha256: String,
    lob_values: u64,
    lob_bytes: u64,
    lob_sha256: String,
    long: String,
}

fn escape(name: &[u8]) -> String {
    let mut s = String::new();
    for &b in name {
        if (0x20..=0x7e).contains(&b) && b != b'\\' {
            s.push(char::from(b));
        } else {
            write!(s, "\\x{b:02x}").unwrap();
        }
    }
    s
}

fn load_manifest() -> Vec<Line> {
    let text = std::fs::read_to_string(root().join("tests/golden/exp_raw.tsv")).unwrap();
    let mut out = Vec::new();
    let mut header_seen = false;
    for l in text.lines().filter(|l| !l.starts_with('#')) {
        if !header_seen {
            assert!(l.starts_with("file\tordinal\tpart\ttable"));
            header_seen = true;
            continue;
        }
        let f: Vec<&str> = l.split('\t').collect();
        assert_eq!(f.len(), 16, "{l}");
        let cols: Vec<(u16, u16)> = f[7]
            .split(',')
            .map(|c| {
                let (t, n) = c.split_once(':').unwrap();
                (t.parse().unwrap(), n.parse().unwrap())
            })
            .collect();
        assert_eq!(cols.len(), f[6].parse::<usize>().unwrap());
        out.push(Line {
            file: f[0].to_string(),
            ordinal: f[1].parse().unwrap(),
            part: f[2].parse().unwrap(),
            table: f[3].to_string(),
            partition: f[4].to_string(),
            subpart: f[5].to_string(),
            cols,
            direct: match f[8] {
                "direct" => true,
                "conv" => false,
                other => panic!("path {other}"),
            },
            rows: f[9].parse().unwrap(),
            nulls: f[10].parse().unwrap(),
            sha256: f[11].to_string(),
            lob_values: f[12].parse().unwrap(),
            lob_bytes: f[13].parse().unwrap(),
            lob_sha256: f[14].to_string(),
            long: f[15].to_string(),
        });
    }
    out
}

fn options() -> WalkOptions {
    WalkOptions {
        hash_fields: true,
        ..WalkOptions::default()
    }
}

fn lines_of(file: &str, report: &WalkReport) -> Vec<Line> {
    let mut out = Vec::new();
    for sec in &report.sections {
        for (k, d) in sec.parts.iter().enumerate() {
            let name_or_dash = |l: &Option<oradmp_core::exp::items::PartitionLine>| {
                l.as_ref().map_or("-".to_string(), |l| escape(&l.name_raw))
            };
            // position:values:sha256 of each LONG / LONG RAW column, as the generator writes them
            let long: Vec<String> = d
                .rows
                .long
                .iter()
                .zip(&d.rows.long_sha256)
                .map(|(st, sha)| format!("{}:{}:{}", st.column, st.values, hex(sha)))
                .collect();
            out.push(Line {
                file: file.to_string(),
                ordinal: sec.ordinal,
                part: u32::try_from(k + 1).unwrap(),
                table: escape(&sec.name_raw),
                partition: name_or_dash(&d.partition),
                subpart: name_or_dash(&d.subpartition),
                cols: d
                    .header
                    .columns
                    .iter()
                    .map(|c| (c.type_code, c.max_len))
                    .collect(),
                direct: d.header.path == PathKind::Direct,
                rows: d.rows.rows,
                nulls: d.rows.nulls,
                sha256: hex(&d.rows.raw_sha256.expect("hashing was requested")),
                lob_values: d.rows.lob.values,
                lob_bytes: d.rows.lob.stored_bytes,
                lob_sha256: d.rows.lob_sha256.map_or("-".to_string(), |h| hex(&h)),
                long: if long.is_empty() {
                    "-".to_string()
                } else {
                    long.join(",")
                },
            });
        }
    }
    out
}

fn exp_files() -> Vec<String> {
    let mut v = Vec::new();
    for f in FOLDERS {
        for e in std::fs::read_dir(fixtures().join(f)).unwrap() {
            let name = e.unwrap().file_name().to_string_lossy().into_owned();
            if name.contains("_exp_") && name.ends_with(".dmp") {
                v.push(format!("{f}/{name}"));
            }
        }
    }
    v.sort();
    v
}

fn walk_all() -> BTreeMap<String, WalkReport> {
    exp_files()
        .into_iter()
        .map(|f| {
            let r = walk_path(&fixtures().join(&f), &options()).unwrap();
            (f, r)
        })
        .collect()
}

#[test]
fn x_walker_with_hashing_reproduces_every_line_of_the_manifest() {
    let manifest = load_manifest();
    // one line per binary part; the three header lines of the file are not parts
    assert_eq!(manifest.len(), TOTALS.parts);
    let files = exp_files();
    assert_eq!(files.len(), TOTALS.files);
    let known: BTreeSet<&String> = files.iter().collect();
    assert!(manifest.iter().all(|l| known.contains(&l.file)));

    let reports = walk_all();
    let mut checked = 0usize;
    for (file, report) in &reports {
        let expected: Vec<&Line> = manifest.iter().filter(|l| &l.file == file).collect();
        let got = lines_of(file, report);
        assert_eq!(got.len(), expected.len(), "{file}: number of parts");
        for (g, e) in got.iter().zip(expected) {
            assert_eq!(g, e, "{file}");
            checked += 1;
        }
    }
    assert_eq!(checked, manifest.len());
    // the manifest is not trivial: partitions, LOB values and LONG columns are in it
    assert_eq!(manifest.iter().filter(|l| l.partition != "-").count(), 18);
    assert_eq!(manifest.iter().filter(|l| l.subpart != "-").count(), 12);
    // N-9 (T-14 g): exact. Counted from `tests/golden/exp_raw.tsv` in python (columns `lob_values` > 0 and `long`
    // != "-"): 21 parts with LOB values (= `TOTALS.lob_sections`, rules v3.5) and 34 with a LONG column (T-19: the four
    // long3 files add four; T-19b: the 14 files long4, long5, longraw4, longraw5 add 14).
    assert_eq!(manifest.iter().filter(|l| l.lob_values > 0).count(), 21);
    assert_eq!(manifest.iter().filter(|l| l.long != "-").count(), 34);
    // rules v3.4: no file stops
    let stopped: Vec<&String> = reports
        .iter()
        .filter(|(_, r)| matches!(r.end, WalkEnd::Stopped(_)))
        .map(|(f, _)| f)
        .collect();
    assert!(stopped.is_empty(), "{stopped:?}");
}

#[test]
fn x_a_changed_field_byte_changes_the_hash_and_nothing_else() {
    // t_nullmix: a table with a few rows; patch the last byte before the end marker of the first
    // non-empty field of the table, in memory.
    let path = fixtures().join("18c/t_nullmix_exp_18c.dmp");
    let bytes = std::fs::read(&path).unwrap();
    let before = walk(Cursor::new(bytes.clone()), &options()).unwrap();
    let d = &before.sections[0].parts[0];
    // the first row starts at rows_offset; find a non-NULL non-empty field and flip one bit in it
    let mut at = usize::try_from(d.header.rows_offset).unwrap();
    let patched_at = loop {
        let len = usize::from(u16::from_le_bytes([bytes[at], bytes[at + 1]]));
        if len != 0 && len != 0xfffe {
            break at + 2;
        }
        at += 2 + if len == 0xfffe { 0 } else { len };
    };
    let mut patched = bytes.clone();
    patched[patched_at] ^= 0x01;
    let after = walk(Cursor::new(patched), &options()).unwrap();
    let a = &after.sections[0].parts[0];
    assert_eq!(a.rows.rows, d.rows.rows);
    assert_eq!(a.rows.nulls, d.rows.nulls);
    assert_ne!(a.rows.raw_sha256, d.rows.raw_sha256);
    assert!(d.rows.raw_sha256.is_some());
    // without the option there is no hash
    let none = walk(Cursor::new(bytes), &WalkOptions::default()).unwrap();
    assert!(none.sections[0].parts[0].rows.raw_sha256.is_none());
}

#[test]
fn x_fields_longer_than_the_smallest_buffer_are_hashed_whole() {
    // the hash must not depend on the buffer size (fields up to 65,533 bytes, buffers from 64 bytes)
    let path = fixtures().join("18c/t_len_exp_18c.dmp");
    let big = walk_path(&path, &options()).unwrap();
    let small = walk_path(
        &path,
        &WalkOptions {
            buffer_bytes: 64,
            ..options()
        },
    )
    .unwrap();
    let h = |r: &WalkReport| r.parts().map(|d| d.rows.raw_sha256).collect::<Vec<_>>();
    assert_eq!(h(&big), h(&small));
    assert!(!h(&big).is_empty());
}

// ---------------------------------------------------------------------------------------------
// rows against truth_counts.txt
// ---------------------------------------------------------------------------------------------

fn truth_counts(version_folder: &str) -> BTreeMap<String, u64> {
    let text = common::truth_text(version_folder, "truth_counts.txt");
    text.lines()
        .filter_map(|l| l.split_once('|'))
        .map(|(t, n)| (t.to_string(), n.trim().parse().unwrap()))
        .collect()
}

#[test]
fn x_rows_per_table_equal_truth_counts_where_the_table_is_listed() {
    let counts = [truth_counts("18c"), truth_counts("11g")];
    assert_eq!(counts[0], counts[1], "the two truth_counts.txt agree");
    let counts = &counts[0];
    let manifest = load_manifest();
    let mut compared = 0usize;
    let mut tables = BTreeSet::new();
    // from the walker, not from the manifest text; the parts of a table add up
    for (file, report) in walk_all() {
        let mut per_table: BTreeMap<(u32, String), u64> = BTreeMap::new();
        for l in lines_of(&file, &report) {
            *per_table.entry((l.ordinal, l.table.clone())).or_default() += l.rows;
        }
        for ((_, table), rows) in per_table {
            if let Some(&n) = counts.get(&table) {
                assert_eq!(rows, n, "{file} {table}");
                compared += 1;
                tables.insert(table.clone());
            }
        }
    }
    // the same on the manifest, so that a wrong manifest line is caught as well
    let mut per_table: BTreeMap<(String, u32, String), u64> = BTreeMap::new();
    for l in &manifest {
        *per_table
            .entry((l.file.clone(), l.ordinal, l.table.clone()))
            .or_default() += l.rows;
    }
    for ((file, _, table), rows) in per_table {
        if let Some(&n) = counts.get(&table) {
            assert_eq!(rows, n, "{file} {table}");
        }
    }
    // N-9 (T-14 g): exact. python over `tests/golden/exp_raw.tsv` and `corpus/fixtures/18c/truth_counts.txt`: of the
    // 436 sections, 170 have a table name listed in the 16 lines of the truth file (T-19: the four T_FRAME
    // sections of the long3 files are new; T-19b: 14 more T_FRAME sections, in the long4, long5, longraw4 and
    // longraw5 files; python over the golden files).
    assert_eq!(compared, 170, "sections compared with truth_counts.txt");
    // every listed table that the exp fixtures contain was compared: T_ROWS is only in corpus/work/, T_FLOAT
    // (BINARY_FLOAT / BINARY_DOUBLE, outside rule T5) is in no exp fixture
    let missing: Vec<&String> = counts.keys().filter(|t| !tables.contains(*t)).collect();
    assert_eq!(missing, ["T_FLOAT", "T_ROWS"]);
}
